function partitionRectangles(nums){const remain=new Set(nums),out=[];while(remain.size){let best=null;for(const n of remain){const r=Math.floor((n-1)/COLS),c=(n-1)%COLS;for(let h=1;h<=ROWS-r;h++)for(let w=1;w<=COLS-c;w++){const cells=[];let ok=true;for(let y=0;y<h&&ok;y++)for(let x=0;x<w;x++){const cell=(r+y)*COLS+c+x+1;if(!remain.has(cell)){ok=false;break}cells.push(cell)}if(ok){const score=cells.length*100+w*2+h;if(!best||score>best.score)best={r,c,w,h,cells,score}}}}if(!best){const n=[...remain][0];best={r:Math.floor((n-1)/COLS),c:(n-1)%COLS,w:1,h:1,cells:[n],score:1}}best.cells.forEach(n=>remain.delete(n));out.push(best)}return out}
